long compat_sock_recvmsg_multiple(int fd, struct compat_mmsghdr __user *mmsg,
                                  unsigned int vlen, unsigned int flags,
                                  struct compat_timespec __user *timeout) {
    struct timespec ktimeout;
    long ret;

    if (timeout) {
        if (get_user(ktimeout.tv_sec, &timeout->tv_sec) ||
            get_user(ktimeout.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;
    } else {
        ktimeout.tv_sec = 0;
        ktimeout.tv_nsec = 0;
    }

    ret = kernel_sock_recvmsg_multiple(fd, (struct mmsghdr __user *)mmsg, vlen,
                                       flags, &ktimeout);

    if (ret >= 0 && timeout) {
        if (put_user(ktimeout.tv_sec, &timeout->tv_sec) ||
            put_user(ktimeout.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;
    }

    return ret;
}

long compat_socket_recvmsg_many(int fd, struct compat_mmsghdr __user *mmsg,
                                unsigned int vlen, unsigned int flags,
                                struct compat_timespec __user *timeout)
{
    struct timespec ktimeout = {0, 0};
    long ret;
    int i;

    if (timeout) {
        compat_timespec_to_timespec(&ktimeout, timeout);
    }

    ret = kernel_recvmsg(fd, mmsg, vlen, flags, timeout ? &ktimeout : NULL);

    if (ret > 0 && timeout) {
        for (i = 0; i < ret; i++) {
            struct compat_mmsghdr cmmsg;
            if (copy_from_user(&cmmsg, mmsg + i, sizeof(cmmsg)))
                return -EFAULT;
            if (copy_to_user(timeout, &ktimeout, sizeof(ktimeout)))
                return -EFAULT;
        }
    }

    return ret;
}

long compat_sock_recvmsg_many(int fd, struct compat_mmsghdr __user *mmsg,
                              unsigned int vlen, unsigned int flags,
                              struct compat_timespec __user *timeout)
{
    long ret;
    struct timespec ktimeout;

    if (timeout) {
        if (get_user(ktimeout.tv_sec, &timeout->tv_sec) ||
            get_user(ktimeout.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;

        if (ktime_set(ktimeout.tv_sec, ktimeout.tv_nsec) < 0)
            return -EINVAL;
    }

    ret = kernel_recvmsg_many(fd, (struct mmsghdr __user *)mmsg, vlen, flags,
                              timeout ? &ktimeout : NULL);

    if (ret >= 0 && timeout && put_user(ktimeout.tv_sec, &timeout->tv_sec) ||
        put_user(ktimeout.tv_nsec, &timeout->tv_nsec))
        return -EFAULT;

    return ret;
}

long compat_recvmmsg_time32(int fd, struct compat_mmsghdr __user *mmsg,
                            unsigned int vlen, unsigned int flags,
                            struct compat_timespec __user *timeout)
{
    struct timespec kernel_timeout;
    long ret;

    if (timeout) {
        if (get_user(kernel_timeout.tv_sec, &timeout->tv_sec) ||
            get_user(kernel_timeout.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;

        if (kernel_timeout.tv_nsec >= NSEC_PER_SEC)
            return -EINVAL;
    }

    ret = kernel_recvmmsg(fd, (struct mmsghdr __user *)mmsg, vlen, flags,
                           timeout ? &kernel_timeout : NULL);

    if (ret > 0 && timeout && ret >= 0) {
        struct compat_timespec user_timeout;

        user_timeout.tv_sec = kernel_timeout.tv_sec;
        user_timeout.tv_nsec = kernel_timeout.tv_nsec;

        if (put_user(user_timeout.tv_sec, &timeout->tv_sec) ||
            put_user(user_timeout.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;
    }

    return ret;
}

